// TypeScript Version: 4.1

import { Complex64Array } from '@stdlib/types/array';

/**
* Interface describing `cany`.
*/
interface Routine {
	/**
	* Tests whether at least one element in a single-precision complex floating-point strided array is truthy.
	*
	* ## Notes
	*
	* -   A complex number is truthy when at least one of its real or imaginary components is truthy.
	* -   The function explicitly treats `NaN` values as falsy.
	*
	* @param N - number of indexed elements
	* @param x - input array
	* @param strideX - stride length
	* @returns boolean indicating whether at least one element is truthy
	*
	* @example
	* var Complex64Array = require( '@stdlib/array/complex64' );
	*
	* var x = new Complex64Array( [ 0.0, 0.0, 1.0, 2.0 ] );
	*
	* var v = cany( x.length, x, 1 );
	* // returns true
	*/
	( N: number, x: Complex64Array, strideX: number ): boolean;

	/**
	* Tests whether at least one element in a single-precision complex floating-point strided array is truthy using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   A complex number is truthy when at least one of its real or imaginary components is truthy.
	* -   The function explicitly treats `NaN` values as falsy.
	*
	* @param N - number of indexed elements
	* @param x - input array
	* @param strideX - stride length
	* @param offsetX - starting index
	* @returns boolean indicating whether at least one element is truthy
	*
	* @example
	* var Complex64Array = require( '@stdlib/array/complex64' );
	*
	* var x = new Complex64Array( [ 0.0, 0.0, 1.0, 2.0 ] );
	*
	* var v = cany.ndarray( x.length, x, 1, 0 );
	* // returns true
	*/
	ndarray( N: number, x: Complex64Array, strideX: number, offsetX: number ): boolean;
}

/**
* Tests whether at least one element in a single-precision complex floating-point strided array is truthy.
*
* ## Notes
*
* -   A complex number is truthy when at least one of its real or imaginary components is truthy.
* -   The function explicitly treats `NaN` values as falsy.
*
* @param N - number of indexed elements
* @param x - input array
* @param strideX - stride length
* @returns boolean indicating whether at least one element is truthy
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var x = new Complex64Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = cany( x.length, x, 1 );
* // returns true
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var x = new Complex64Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = cany.ndarray( x.length, x, 1, 0 );
* // returns true
*/
declare var cany: Routine;


// EXPORTS //

export = cany;
